CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL);
CREATE TABLE permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, email VARCHAR(160) NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, is_super_admin TINYINT(1) NOT NULL DEFAULT 0, status ENUM('active','inactive') NOT NULL DEFAULT 'active', last_login_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL, INDEX(status));
CREATE TABLE user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE);
CREATE TABLE role_permissions (role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE settings (setting_key VARCHAR(120) PRIMARY KEY, setting_value TEXT NULL, updated_at TIMESTAMP NULL);
CREATE TABLE store (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, address TEXT, phone VARCHAR(40), whatsapp VARCHAR(40), email VARCHAR(160), working_hours TEXT, maps_url TEXT, maps_embed TEXT, directions_url TEXT, hero_image VARCHAR(255), exterior_image VARCHAR(255), updated_at TIMESTAMP NULL);
CREATE TABLE collections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, short_description TEXT, long_description MEDIUMTEXT, cover_image VARCHAR(255), hero_image VARCHAR(255), status ENUM('active','inactive') DEFAULT 'active', sort_order INT DEFAULT 0, featured TINYINT(1) DEFAULT 0, seo_title VARCHAR(180), meta_description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL, INDEX(status,featured,sort_order));
CREATE TABLE subcollections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, collection_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, slug VARCHAR(180) NOT NULL, description TEXT, image VARCHAR(255), hero_image VARCHAR(255), status ENUM('active','inactive') DEFAULT 'active', sort_order INT DEFAULT 0, featured TINYINT(1) DEFAULT 0, seo_title VARCHAR(180), meta_description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL, UNIQUE(collection_id,slug), FOREIGN KEY(collection_id) REFERENCES collections(id) ON DELETE CASCADE);
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, collection_id BIGINT UNSIGNED NOT NULL, subcollection_id BIGINT UNSIGNED NULL, name VARCHAR(180) NOT NULL, slug VARCHAR(190) NOT NULL UNIQUE, short_description TEXT, long_description MEDIUMTEXT, technical_details JSON NULL, main_image VARCHAR(255), status ENUM('active','inactive') DEFAULT 'active', featured TINYINT(1) DEFAULT 0, sort_order INT DEFAULT 0, seo_title VARCHAR(180), meta_description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL, FOREIGN KEY(collection_id) REFERENCES collections(id), FOREIGN KEY(subcollection_id) REFERENCES subcollections(id) ON DELETE SET NULL, INDEX(status,featured,sort_order));
CREATE TABLE product_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, path VARCHAR(255) NOT NULL, alt_text VARCHAR(180), sort_order INT DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE applications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, slug VARCHAR(190) NOT NULL UNIQUE, description TEXT, content MEDIUMTEXT, main_image VARCHAR(255), status ENUM('active','inactive') DEFAULT 'active', featured TINYINT(1) DEFAULT 0, sort_order INT DEFAULT 0, seo_title VARCHAR(180), meta_description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL);
CREATE TABLE application_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, application_id BIGINT UNSIGNED NOT NULL, path VARCHAR(255) NOT NULL, alt_text VARCHAR(180), sort_order INT DEFAULT 0, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE);
CREATE TABLE media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, disk VARCHAR(40) DEFAULT 'local', path VARCHAR(255) NOT NULL, original_name VARCHAR(190), alt_text VARCHAR(180), mime_type VARCHAR(100), size_bytes BIGINT UNSIGNED, usage_area VARCHAR(80), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(usage_area));
CREATE TABLE homepage_sections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, section_key VARCHAR(80) NOT NULL, title VARCHAR(180), description TEXT, image VARCHAR(255), mobile_image VARCHAR(255), cta_label VARCHAR(80), cta_url VARCHAR(255), status ENUM('active','inactive') DEFAULT 'active', sort_order INT DEFAULT 0, updated_at TIMESTAMP NULL);
CREATE TABLE menus (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100), location VARCHAR(40) NOT NULL UNIQUE, status ENUM('active','inactive') DEFAULT 'active');
CREATE TABLE menu_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, menu_id BIGINT UNSIGNED NOT NULL, label VARCHAR(100) NOT NULL, url VARCHAR(255) NOT NULL, target VARCHAR(20) DEFAULT '_self', status ENUM('active','inactive') DEFAULT 'active', sort_order INT DEFAULT 0, FOREIGN KEY(menu_id) REFERENCES menus(id) ON DELETE CASCADE);
CREATE TABLE seo (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, entity_type VARCHAR(80), entity_id BIGINT UNSIGNED NULL, path VARCHAR(255), title VARCHAR(180), meta_description VARCHAR(255), canonical_url VARCHAR(255), og_title VARCHAR(180), og_description VARCHAR(255), og_image VARCHAR(255), robots VARCHAR(80) DEFAULT 'index,follow', UNIQUE(entity_type,entity_id), INDEX(path));
CREATE TABLE contact_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(160), phone VARCHAR(40), email VARCHAR(160), subject VARCHAR(180), message TEXT, related_type VARCHAR(80), related_id BIGINT UNSIGNED NULL, status ENUM('new','contacted','closed') DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL, INDEX(status,created_at));
CREATE TABLE whatsapp_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, context VARCHAR(80), message TEXT, ip VARCHAR(64), user_agent VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_user_id BIGINT UNSIGNED NULL, action VARCHAR(120), description TEXT, subject_type VARCHAR(80), subject_id BIGINT UNSIGNED NULL, ip VARCHAR(64), user_agent VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX(action,created_at));
CREATE TABLE login_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED, ip VARCHAR(64), user_agent VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE failed_logins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, login VARCHAR(160), ip VARCHAR(64), user_agent VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(login,ip,created_at));
CREATE TABLE sessions (id VARCHAR(128) PRIMARY KEY, user_id BIGINT UNSIGNED NULL, payload MEDIUMTEXT, last_activity INT UNSIGNED, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE backups (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, filename VARCHAR(190), size_bytes BIGINT UNSIGNED DEFAULT 0, status ENUM('created','failed') DEFAULT 'created', created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
